<?php if($is_admin): ?><script>
$(function(){
 const filters=document.getElementById('documentRegistryFilters');
 const table=document.getElementById('documentsTable');
 if(!filters||!table||!$.fn.DataTable)return;
 const value=key=>filters.querySelector('[data-filter="'+key+'"]')?.value||'';
 $.fn.dataTable.ext.search.push(function(settings,data,index){
  if(settings.nTable!==table)return true;
  const row=settings.aoData[index]?.nTr;
  if(!row)return true;
  const exact=(key,attribute)=>!value(key)||value(key)===row.dataset[attribute];
  if(!exact('employee','employeeCode')||!exact('type','type')||!exact('category','category')||!exact('status','status'))return false;
  const issue=row.dataset.issue||'';
  if(value('from')&&(!issue||issue<value('from')))return false;
  if(value('to')&&(!issue||issue>value('to')))return false;
  const expiry=row.dataset.expiry||'';
  const mode=value('expiration');
  if(!mode)return true;
  if(mode==='No Expiration')return expiry==='';
  if(!expiry)return false;
  const today=new Date();today.setHours(0,0,0,0);
  const date=new Date(expiry+'T00:00:00');
  const remaining=Math.round((date-today)/86400000);
  if(mode==='Expired')return remaining<0;
  const days=Math.max(1,Math.min(365,parseInt(value('days'),10)||60));
  return mode==='Expiring Soon'?remaining>=0&&remaining<=days:remaining>days;
 });
 $(filters).on('change input','select,input',function(){if($.fn.DataTable.isDataTable(table))$(table).DataTable().draw()});
});
</script><?php endif; ?>
